export function createLedger({ expectedAmounts = {} } = {}) {
  const records = new Map();
  const handledIds = new Set();

  const knownTypes = new Set([
    "charge.success",
    "charge.failed",
    "charge.abandoned",
    "refund.processed",
  ]);

  const terminalChargeStatuses = new Set([
    "success",
    "partially_refunded",
    "refunded",
    "amount_mismatch",
  ]);

  function hasExpectedAmount(reference) {
    return Object.prototype.hasOwnProperty.call(expectedAmounts, reference);
  }

  function result(applied, reason, record) {
    return {
      applied,
      reason,
      status: record ? record.status : null,
    };
  }

  function applyRefund(record, amountKobo) {
    const nextTotal = record.refundedKobo + amountKobo;

    if (record.status === "refunded" || nextTotal > record.amountKobo) {
      return result(false, "over-refund", record);
    }

    record.refundedKobo = nextTotal;
    record.status =
      nextTotal === record.amountKobo ? "refunded" : "partially_refunded";

    return result(true, null, record);
  }

  function handle(event) {
    if (!event || !knownTypes.has(event.type)) {
      return result(false, "unknown-type");
    }

    if (handledIds.has(event.id)) {
      return result(false, "duplicate", records.get(event.reference));
    }

    if (
      (event.type === "charge.success" || event.type === "refund.processed") &&
      (!Number.isInteger(event.amountKobo) || event.amountKobo <= 0)
    ) {
      return result(false, "invalid-amount", records.get(event.reference));
    }

    handledIds.add(event.id);

    let record = records.get(event.reference);

    if (!record) {
      record = {
        reference: event.reference,
        status: "pending",
        amountKobo: hasExpectedAmount(event.reference)
          ? expectedAmounts[event.reference]
          : null,
        refundedKobo: 0,
        deferredRefunds: [],
      };
      records.set(event.reference, record);
    }

    if (event.type === "refund.processed") {
      if (record.status === "amount_mismatch") {
        return result(false, "terminal", record);
      }

      if (
        record.status === "pending" ||
        record.status === "abandoned" ||
        record.status === "failed"
      ) {
        record.deferredRefunds.push(event.amountKobo);
        return result(false, "deferred", record);
      }

      return applyRefund(record, event.amountKobo);
    }

    if (terminalChargeStatuses.has(record.status)) {
      return result(false, "terminal", record);
    }

    if (event.type === "charge.failed") {
      if (record.status === "failed") {
        return result(false, "stale", record);
      }

      record.status = "failed";
      return result(true, null, record);
    }

    if (event.type === "charge.abandoned") {
      if (record.status !== "pending") {
        return result(false, "stale", record);
      }

      record.status = "abandoned";
      return result(true, null, record);
    }

    const expectedKnown = hasExpectedAmount(event.reference);
    const expectedAmount = expectedKnown
      ? expectedAmounts[event.reference]
      : null;

    if (expectedKnown && event.amountKobo !== expectedAmount) {
      record.status = "amount_mismatch";
      record.deferredRefunds.length = 0;
      return result(true, "amount-mismatch", record);
    }

    record.amountKobo = expectedKnown ? expectedAmount : event.amountKobo;
    record.status = "success";

    for (const amountKobo of record.deferredRefunds) {
      applyRefund(record, amountKobo);
    }
    record.deferredRefunds.length = 0;

    return result(true, null, record);
  }

  function get(reference) {
    const record = records.get(reference);
    if (!record) {
      return undefined;
    }

    return {
      reference: record.reference,
      status: record.status,
      amountKobo: record.amountKobo,
      refundedKobo: record.refundedKobo,
    };
  }

  return { handle, get };
}
